import clsx from 'clsx'
import type {
  AriaAttributes,
  KeyboardEventHandler,
  MouseEventHandler,
  PropsWithChildren,
  Ref,
} from 'react'
import React, { forwardRef } from 'react'
import { toDataSet } from '../utilities/toDataSet'

export interface IconButtonProps {
  /**
   * Accessible label for the icon button.
   * Required for screen readers
   */
  'aria-label': AriaAttributes['aria-label']
  /**
   * Identifies the element whose contents or presence are controlled by the icon button
   */
  'aria-controls'?: AriaAttributes['aria-controls']
  /**
   * Indicates whether the element controlled by the icon button is expanded or collapsed
   */
  'aria-expanded'?: AriaAttributes['aria-expanded']
  /**
   * Indicates the availability and type of interactive popup element that can be triggered by the button
   */
  'aria-haspopup'?: AriaAttributes['aria-haspopup']
  /**
   * Identifies the element (or elements) that labels the button.
   */
  'aria-labelledby'?: AriaAttributes['aria-labelledby']
  /**
   * The color scheme of the icon button
   * @default 'default'
   */
  color?: IconButtonColor
  /**
   * Custom data attributes to be added to the button element
   */
  dataSet?: Record<string, string | undefined>
  /**
   * If true, the button is disabled
   * @default false
   */
  disabled?: boolean
  /**
   * The id attribute of the button element
   */
  id?: string
  /**
   * Callback fired when the button is activated
   */
  onClick?: MouseEventHandler<HTMLButtonElement>
  /**
   * Callback fired when a key is pressed while the button is focused
   */
  onKeyDown?: KeyboardEventHandler<HTMLButtonElement>
  /**
   * The size of the icon button
   * @default 'small'
   */
  size?: IconButtonSize
  /** Tab order index for keyboard navigation.
   * Only adjust this if you want the user’s tab order to be non-standard or removed entirely
   * @default 0
   */
  tabIndex?: number
  /** The type attribute of the button element
   * @default 'button'
   */
  type?: IconButtonType
  /**
   * The visual style variant of the icon button
   * @default 'text'
   */
  variant?: IconButtonVariant
}

export type IconButtonColor =
  | 'error'
  | 'default'
  | 'inverse'
  | 'primary'
  | 'secondary'

type IconButtonColors = {
  [key in IconButtonColor]: string
}

type IconButtonSize = 'large' | 'medium' | 'base' | 'small'

type IconButtonSizes = {
  [key in IconButtonSize]: string
}

type IconButtonType = 'button' | 'reset' | 'submit'

export type IconButtonVariant = 'contained' | 'outlined' | 'text'

type IconButtonVariants = {
  [key in IconButtonVariant]: IconButtonColors
}

type IconButtonDisabledVariants = {
  [key in IconButtonVariant]: {
    default: string
    inverse: string
  }
}

const disabledVariants: IconButtonDisabledVariants = {
  contained: {
    default: `disabled:bg-black-15 disabled:text-black-30`,
    inverse: `disabled:bg-white-15 disabled:text-white-30`,
  },
  outlined: {
    default: `disabled:bg-transparent disabled:border-black-15 disabled:text-black-30`,
    inverse: `disabled:bg-transparent disabled:border-white-30 disabled:text-white-30`,
  },
  text: {
    default: `disabled:bg-transparent disabled:text-black-25`,
    inverse: `disabled:bg-transparent disabled:text-white-30`,
  },
}

const variants: IconButtonVariants = {
  contained: {
    error: `bg-error-main text-white-100 ${disabledVariants.contained.default} active:bg-error-darker focus:bg-error-dark focus-visible:ring hover:bg-error-dark`,
    default: `bg-black-5 text-black-90 ${disabledVariants.contained.default} active:bg-black-25 focus:bg-black-15 focus-visible:ring hover:bg-black-15`,
    inverse: `bg-white-25 text-white-100 ${disabledVariants.contained.inverse} active:bg-white-60 focus:bg-white-45 focus-visible:ring hover:bg-white-45`,
    primary: `bg-primary-main text-white-100 ${disabledVariants.contained.default} active:bg-primary-darker focus:bg-primary-dark focus-visible:ring hover:bg-primary-dark`,
    secondary: `bg-secondary-main text-white-100 ${disabledVariants.contained.default} active:bg-secondary-darker focus:bg-secondary-dark focus-visible:ring hover:bg-secondary-dark`,
  },
  outlined: {
    error: `border border-solid border-error-darker text-error-darker ${disabledVariants.outlined.default} active:bg-error-20 focus:bg-error-10 focus-visible:ring hover:bg-error-10`,
    default: `border border-solid border-black-20 text-black-90 ${disabledVariants.outlined.default} active:bg-black-15 focus:bg-black-5 focus-visible:ring hover:bg-black-5`,
    inverse: `border border-solid border-white-100 text-white-100 ${disabledVariants.outlined.inverse} active:bg-white-45 focus:bg-white-25 focus-visible:ring hover:bg-white-25`,
    primary: `border border-solid border-primary-main text-primary-main ${disabledVariants.outlined.default} active:bg-primary-20 focus:bg-primary-10 focus-visible:ring hover:bg-primary-10`,
    secondary: `border border-solid border-secondary-main text-secondary-main ${disabledVariants.outlined.default} active:bg-secondary-20 focus:bg-secondary-10 focus-visible:ring hover:bg-secondary-10`,
  },
  text: {
    error: `text-error-main hover:bg-error-10 focus:bg-error-10 focus-visible:ring active:bg-error-20 ${disabledVariants.text.default}`,
    default: `text-black-60 hover:bg-black-5 focus:bg-black-5 focus-visible:ring active:bg-black-15 ${disabledVariants.text.default}`,
    inverse: `text-white-100 hover:bg-white-25 focus:bg-white-25 focus-visible:ring active:bg-white-45 ${disabledVariants.text.inverse}`,
    primary: `text-primary-main hover:bg-primary-10 focus:bg-primary-10 focus-visible:ring active:bg-primary-20 ${disabledVariants.text.default}`,
    secondary: `text-secondary-main hover:bg-secondary-10 focus:bg-secondary-10 focus-visible:ring active:bg-secondary-20 ${disabledVariants.text.default}`,
  },
}

const sizes: IconButtonSizes = {
  large: 'w-15 h-15 p-3',
  medium: 'w-12 h-12 p-3',
  base: 'w-10 h-10 p-2',
  small: 'w-7 h-7 p-0.5',
}

export function Component(
  {
    'aria-label': label,
    'aria-controls': controls,
    'aria-expanded': expanded,
    'aria-haspopup': hasPopup,
    'aria-labelledby': labelledBy,
    children,
    color = 'default',
    dataSet,
    disabled = false,
    id,
    onClick,
    onKeyDown,
    size = 'small',
    tabIndex = 0,
    type = 'button',
    variant = 'text',
  }: PropsWithChildren<IconButtonProps>,
  ref?: Ref<HTMLButtonElement>,
): JSX.Element {
  return (
    <button
      aria-controls={controls}
      aria-expanded={expanded}
      aria-haspopup={hasPopup}
      aria-label={label}
      aria-labelledby={labelledBy}
      className={clsx(
        'shrink-0 rounded-full disabled:cursor-not-allowed focus:outline-none',
        variants[variant][color],
        sizes[size],
      )}
      {...toDataSet(dataSet)}
      disabled={disabled}
      id={id}
      onClick={onClick}
      onKeyDown={onKeyDown}
      ref={ref}
      tabIndex={tabIndex}
      type={type}
    >
      {children}
    </button>
  )
}

const IconButton = forwardRef<
  HTMLButtonElement,
  PropsWithChildren<IconButtonProps>
>(Component)

IconButton.displayName = 'IconButton'

export default IconButton
